def get_user_ip():
    return requests.get('https://api.ipify.org').text

def get_cpu_load():
    return os.popen('wmic csproduct get name').read().split('Name:')[1].split('Usage')[0]

def get_gpu_load():
    return os.popen('wmic csproduct get name').read().split('Name:')[1].split('Usage')[0]

def get_ram_load():
    return os.popen('wmic csproduct get name').read().split('Name:')[1].split('Usage')[0]

def get_disk_load():
    return os.popen('wmic csproduct get name').read().split('Name:')[1].split('Usage')[0]

def get_hashrate():
    return os.popen('cat /proc/stat | grep "hashrate" | awk -F " " '{print $2}' | head -n 1').read()
